{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:umf:parquet:rename:0.1.0",
  "type": "object",
  "required": [
    "source",
    "status",
    "complete",
    "diagnostics"
  ],
  "properties": {
    "source": {
      "$ref": "urn:umf:core:0.10.0"
    },
    "status": {
      "enum": [
        "transformed",
        "blocked"
      ]
    },
    "complete": {
      "const": false
    },
    "diagnostics": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "code": {
            "type": "string"
          },
          "path": {
            "type": "string"
          },
          "severity": {
            "enum": [
              "error",
              "warning"
            ]
          },
          "message": {
            "type": "string"
          }
        },
        "required": [
          "code",
          "path",
          "severity",
          "message"
        ],
        "additionalProperties": false
      }
    },
    "output": {
      "$ref": "urn:umf:core:0.10.0"
    },
    "unchangedPrefixBytes": {
      "type": "integer",
      "minimum": 4
    },
    "rename": {
      "type": "object",
      "required": [
        "index",
        "from",
        "to"
      ],
      "properties": {
        "index": {
          "type": "integer",
          "minimum": 1
        },
        "from": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string"
          }
        },
        "to": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string"
          }
        }
      },
      "additionalProperties": false
    }
  },
  "additionalProperties": false,
  "allOf": [
    {
      "if": {
        "properties": {
          "status": {
            "const": "transformed"
          }
        }
      },
      "then": {
        "properties": {
          "output": true,
          "rename": true,
          "unchangedPrefixBytes": true
        },
        "required": [
          "output",
          "rename",
          "unchangedPrefixBytes"
        ]
      },
      "else": {
        "not": {
          "anyOf": [
            {
              "properties": {
                "output": true
              },
              "required": [
                "output"
              ]
            },
            {
              "properties": {
                "rename": true
              },
              "required": [
                "rename"
              ]
            },
            {
              "properties": {
                "unchangedPrefixBytes": true
              },
              "required": [
                "unchangedPrefixBytes"
              ]
            }
          ]
        }
      }
    }
  ]
}
